import { db } from "./db";

export async function suspendAccount(userId: string): Promise<void> {
  await db.transaction(async (tx) => {
    await tx.query("UPDATE users SET status = 'suspended' WHERE id = $1", [userId]);
    await tx.query("DELETE FROM sessions WHERE user_id = $1", [userId]);
  });
}

export async function deleteAccount(userId: string): Promise<void> {
  await db.transaction(async (tx) => {
    await tx.one<{ email: string }>("SELECT email FROM users WHERE id = $1 FOR UPDATE", [userId]);
    await tx.query("UPDATE users SET status = 'deleted', name = '', phone = NULL WHERE id = $1", [userId]);
    await tx.query("DELETE FROM sessions WHERE user_id = $1", [userId]);
  });
}
